  trace(signal) {
    const following = [];
    function visit(current, depth) {
      following.push(`${' '.repeat(2 * depth)}${current.name} <- ${current.origin}`);
      for (const ingredient of current.ingredients) visit(ingredient, depth + 1);
    }
    visit(signal, 1);
    return { details: signal.name, following };
